"""Offline read-only cognitive journal audit. Inputs must be quiescent."""
import hashlib
import json
from pathlib import Path
import shutil
import sqlite3
import tempfile
import zlib


def audit(path: Path) -> dict:
    checked = 0
    try:
        source = Path(path).resolve(strict=True)
        if not source.is_file():
            raise ValueError('input is not a regular file')
        # SQLite may create or update SHM even in mode=ro. Audit a private copy,
        # retaining WAL recovery semantics without touching source sidecars.
        with tempfile.TemporaryDirectory(prefix='journal-audit-') as directory:
            target = Path(directory) / 'audit.db'
            shutil.copyfile(source, target)
            for suffix in ('-wal', '-journal'):
                sidecar = Path(str(source) + suffix)
                if sidecar.exists():
                    shutil.copyfile(sidecar, str(target) + suffix)
            db = sqlite3.connect(target.as_uri() + '?mode=ro', uri=True)
            try:
                db.execute('PRAGMA query_only=ON')
                if db.execute('PRAGMA integrity_check').fetchall() != [('ok',)]:
                    raise ValueError('SQLite integrity check failed')
                previous = '0' * 64
                for seq, kind, parent, digest, payload, spikes in db.execute(
                    'SELECT seq,kind,previous_hash,hash,payload,spikes FROM records ORDER BY seq'
                ):
                    checked += 1
                    parsed = json.loads(payload)
                    if (seq != checked or parent != previous or parsed.get('kind') != kind
                        or hashlib.sha256(parent.encode() + payload.encode()).hexdigest() != digest):
                        raise ValueError(f'record chain differs at sequence {seq}')
                    if spikes is None and "spikes_sha256" in parsed:
                        raise ValueError(f'missing spike evidence at sequence {seq}')
                    if spikes is not None:
                        raw = zlib.decompress(spikes)
                        if hashlib.sha256(raw).hexdigest() != parsed.get('spikes_sha256'):
                            raise ValueError(f'spike evidence differs at sequence {seq}')
                    previous = digest
                row = db.execute('SELECT metadata FROM checkpoint WHERE id=1').fetchone()
                if row is None:
                    if checked:
                        raise ValueError('history exists without checkpoint')
                else:
                    metadata = json.loads(row[0])
                    if metadata['record_seq'] != checked or metadata['record_head'] != previous:
                        raise ValueError('checkpoint sequence or head differs')
                return {'valid': True, 'checked': checked, 'head': previous}
            finally:
                db.close()
    except Exception as exc:
        return {'valid': False, 'checked': checked, 'reason': f'{type(exc).__name__}: {exc}'}


def main():
    import argparse
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('database', type=Path)
    args = parser.parse_args()
    result = audit(args.database)
    print(json.dumps(result))
    return 0 if result['valid'] else 1


if __name__ == '__main__':
    raise SystemExit(main())

