"""Read-only publication policy check of Git stage-0 blobs (Python 3.12)."""
import argparse
import json
import os
from pathlib import Path
import re
import subprocess

RULES = (
    ("local identity path", r"/" r"Users/[^/\s]+/|[A-Z]:\\\\Users\\\\"),
    (
        "conversation annotation",
        r"(?i)\b(?:the user (?:asked|requested|instructed)|owner(?:['’]s)? request|in this " r"chat|conversation_" r"id|thread_" r"id)\b",
    ),
    ("credential", r"\b(?:privy_app_secret_|fapi_|jup_)[A-Za-z0-9_-]{24,}"),
    (
        "OpenAI credential",
        r"\bsk-(?:(?:proj|svcacct)-[A-Za-z0-9_-]{32,}|[A-Za-z0-9]{32,})(?![A-Za-z0-9_-])",
    ),
    ("bot credential", r"\b[0-9]{8,12}:[A-Za-z0-9_-]{30,}"),
    (
        "private key",
        r"-----BEGIN (?:EC |RSA |OPENSSH )?PRIVATE KEY-----[\s\S]{32,}?-----END",
    ),
)

SCOPE = "Git index stage-0 snapshot; not worktree or historical audit"

class IndexCheckError(RuntimeError):
    """The snapshot could not be checked; never a clean verdict."""


def _git(root, *args):
    # Do not inherit repository/index redirection or optional write behavior.
    env = {k: v for k, v in os.environ.items() if not k.startswith("GIT_")}
    env.update(GIT_OPTIONAL_LOCKS="0", GIT_NO_REPLACE_OBJECTS="1",
               GIT_NO_LAZY_FETCH="1", GIT_TERMINAL_PROMPT="0")
    try:
        p = subprocess.run(["git", *args], cwd=root, env=env,
                           stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                           timeout=60, check=False)
    except (OSError, subprocess.TimeoutExpired) as exc:
        raise IndexCheckError("Git operation unavailable") from exc
    if p.returncode:
        # Git stderr may contain sensitive filenames/content. Do not relay it.
        raise IndexCheckError("Git operation failed")
    return p.stdout


def check_index(root):
    """Return a JSON-compatible report; raise IndexCheckError on incomplete scans.

    Root may be a directory inside the working repository. Git environment
    overrides are deliberately ignored. No files or index entries are updated.
    """
    top = _git(Path(root), "rev-parse", "--show-toplevel").removesuffix(b"\n")
    root = Path(os.fsdecode(top))
    raw = _git(root, "ls-files", "--stage", "--full-name", "-z")
    entries = []
    try:
        if raw and not raw.endswith(b"\0"):
            raise ValueError()
        for record in raw.split(b"\0"):
            if not record:
                continue
            meta, name = record.split(b"\t", 1)
            mode, oid, stage = meta.split(b" ")
            if stage != b"0":
                raise IndexCheckError("Unresolved index entries")
            if mode not in (b"100644", b"100755", b"120000", b"160000"):
                raise IndexCheckError("Unsupported index mode")
            if not re.fullmatch(rb"[0-9a-f]{40}|[0-9a-f]{64}", oid):
                raise ValueError()
            entries.append((mode, oid, name))
    except ValueError as exc:
        raise IndexCheckError("Invalid index listing") from exc
    checked, failures = 0, []
    for mode, oid, name in entries:
        if mode == b"160000" or name == b"scripts/check_publication.py":
            continue
        blob = _git(root, "cat-file", "blob", oid.decode("ascii"))
        try:
            # Match baseline read_text universal newline behavior.
            content = blob.decode("utf-8").replace("\r\n", "\n").replace("\r", "\n")
        except UnicodeDecodeError:
            continue
        checked += 1
        for label, pattern in RULES:
            if re.search(pattern, content):
                failures.append({"path": os.fsdecode(name), "rule": label})
    return {"checked_text_files": checked,
            "private_material_detected": bool(failures),
            "scope": SCOPE, "failures": failures}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo", required=True, type=Path)
    args = parser.parse_args()
    try:
        report = check_index(args.repo)
    except IndexCheckError as exc:
        print(json.dumps({"checked_text_files": 0,
                          "private_material_detected": None, "scope": SCOPE,
                          "failures": [], "error": str(exc)}))
        return 2
    print(json.dumps(report, ensure_ascii=True))
    return 1 if report["private_material_detected"] else 0


if __name__ == "__main__":
    raise SystemExit(main())
